after.content:
$ErrorActionPreference = 'Stop'
$root = Split-Path -Parent $PSScriptRoot
Push-Location $root
try {
  & node .\scripts\verify-generated.mjs
  if ($LASTEXITCODE -ne 0) { throw "generated contract verification failed: $LASTEXITCODE" }
  & node .\scripts\verify-api-baseline.mjs
  if ($LASTEXITCODE -ne 0) { throw "API baseline verification failed: $LASTEXITCODE" }
  & node .\scripts\verify-module-boundaries.mjs
  if ($LASTEXITCODE -ne 0) { throw "module boundary verification failed: $LASTEXITCODE" }
  & .\gradlew.bat :ji-extension-api:test :ji-resource-local:test :ji-agent-core:test :ji-test-kit:test --offline --rerun-tasks --no-daemon
  if ($LASTEXITCODE -ne 0) { throw "resource/trust tests failed: $LASTEXITCODE" }
} finally {
  Pop-Location
}
